INSERT INTO faqs (question, answer, sort_order) VALUES
('How do I track my order?', 'After placing an order, you''ll receive a confirmation email with a tracking number. You can also find real-time tracking updates by clicking on any order in your history above. Delivery notifications are sent automatically.', 1),
('What''s your return policy?', 'Books can be returned within thirty days of purchase if they remain in original condition. Shipping is free for returns. Once received, refunds are processed within five business days to your original payment method.', 2),
('Can I modify my order?', 'Orders can be modified within one hour of placement. After that, the order enters our fulfillment process and cannot be changed. Contact us immediately with your order number and requested changes.', 3),
('How long does shipping take?', 'Standard shipping takes five to seven business days. Express delivery is available at checkout for two to three business day delivery. Free shipping is included on orders over fifty dollars.', 4),
('Do you ship internationally?', 'Yes, we ship to most countries worldwide. International delivery typically takes ten to fourteen business days. Customs duties and taxes may apply depending on your destination and local regulations.', 5);
